import type { StoryBundle } from "@/components/story/types";
import { story } from "./story";
import { formations } from "./formations";
import { faces } from "./faces";
import { looks } from "./looks";
import { copy } from "./copy";
import { extras } from "./extras";
import { links } from "./links";

export const bundle = { story, formations, faces, looks, copy, extras, links, defaultLook: "light" } satisfies StoryBundle;
import type { StoryDef, BeatIdOf } from "../lib/story/story.ts";

export const story = {
  pieces: 7,
  chapters: [
    { id: "opening", number: 1, name: "Gather", role: "opening", beats: [{ id: "opening.gather", height: 2 }] },
    { id: "middle", number: 2, name: "Open", role: "how", beats: [{ id: "middle.fan", height: 1 }] },
    { id: "close", number: 3, name: "Whole", role: "close", beats: [{ id: "close.whole", height: 1 }] },
  ],
} as const satisfies StoryDef;

export type BeatId = BeatIdOf<typeof story>;
import { blankFormation, type BeatFormation, type Formation, type Pose } from "../lib/story/formation.ts";
import { fan, measure, scatter, stack } from "../lib/story/layouts.ts";
import { story, type BeatId } from "./story.ts";

function formation(pieces: Pose[]): Formation {
  const bounds = measure(pieces);
  return {
    ...blankFormation(story.pieces), pieces,
    span: bounds.span * 1.15, rise: bounds.rise * 1.15,
    anchor: [0.42, 0.16], turn: [0.12, -0.12], near: 5,
    floor: -3.5,
  };
}

const size: [number, number] = [1.4, 1.9];
export const formations = {
  "opening.gather": {
    rest: formation(scatter(story.pieces, size)),
    within: formation(stack(story.pieces, size, { offset: [0.018, 0.012, -0.07] })),
  },
  "middle.fan": { rest: formation(fan(story.pieces, size)) },
  "close.whole": { rest: formation(stack(story.pieces, size, { offset: [0.018, 0.012, -0.07] })) },
} satisfies Record<BeatId, BeatFormation>;
export const copy = {
  lang: "en",
  metadata: { title: "Storyfolio | A plain story", description: "A small story for testing the Storyfolio scroll engine." },
  railLabel: "Chapters",
  lookLabel: "Appearance",
  fpsLabel: "Frames per second",
  skipLabel: "Skip to the ending",
  backLabel: "Gather again",
  pictureAlt: "Seven cards opened into a fan, a static version of the scene.",
  faceWords: ["Gather", "Open", "Whole", "One", "Story", "Seven", "Pieces"],
  beats: {
    "opening.gather": {
      title: "One story, seven pieces.",
      body: "This is the engine's test story. Scroll to bring seven scattered cards together, open them, and return them to a whole.",
      note: "The first beat gathers as you scroll. Gather, Open, Whole, One, Story, Seven and Pieces are the words on the cards.",
    },
    "middle.fan": {
      title: "Room to see each piece.",
      body: "The same seven cards open into a fan. A simple line arrives with this chapter, loaded only when you come near it.",
      note: "This schematic tests a chapter's extra shape. The text and the flat illustration also explain it without a canvas.",
    },
    "close.whole": {
      title: "The pieces belong together.",
      body: "The cards close into one stack. The story, its text and its links stay readable when the scene cannot run.",
      note: "The link on the front card is an ordinary keyboard-accessible link. The same destination is here in the text.",
    },
  },
};
import type { Look } from "../lib/story/looks.ts";

export const looks = [
  {
    id: "light", name: "Light", ground: "#f2f0e9", ink: "#202932", faint: "#58636c", accent: "#8d471e",
    surface: { color: "#fffdf8", roughness: 0.9, glows: false },
    lights: { ambient: 1.5, key: 2, fill: 0.5, rim: 0.6 }, floor: "matte", shadows: true,
  },
  {
    id: "dark", name: "Dark", ground: "#151e27", ink: "#f3eee2", faint: "#abb9c4", accent: "#efb475",
    surface: { color: "#283745", roughness: 0.8, glows: false },
    lights: { ambient: 1.4, key: 2, fill: 0.7, rim: 1 }, floor: "matte", shadows: true,
  },
] as const satisfies readonly Look[];
import type { ComponentType, RefObject } from "react";
import type { MeshStandardMaterial } from "three";
import type { BeatFormation } from "@/lib/story/formation";
import type { StoryDef } from "@/lib/story/story";
import type { Look } from "@/lib/story/looks";
import type { Controls } from "@/lib/story/controls";
import type { Frame } from "./conductor";

export type FaceDef = {
  id: string;
  beat: string;
  piece: number;
  src?: string;
  draw?: (context: CanvasRenderingContext2D, width: number, height: number, look: Look) => void;
};
export type StoryLink = { beat: string; piece: number; href: string; label: string };
/** Frame callbacks in optional extras use useExtraFrame to contain failures. */
export type ExtraProps = { frameRef: RefObject<Frame>; look: Look; still: boolean; controls: Controls };
export type PieceProps = { index: number; material: MeshStandardMaterial; look: Look };
export type StoryBundle = {
  story: StoryDef;
  formations: Record<string, BeatFormation>;
  faces: readonly FaceDef[];
  looks: readonly Look[];
  defaultLook?: string;
  copy: { railLabel: string; lookLabel: string; fpsLabel?: string };
  extras?: readonly { chapter: string; load: () => Promise<{ default: ComponentType<ExtraProps> }> }[];
  links?: readonly StoryLink[];
  Piece?: ComponentType<PieceProps>;
};
import { Chapter, Beat, Kicker, Title, Body, Note } from "@/components/story/chapter";
import { Experience } from "@/content/experience";
import { story } from "@/content/story";
import { copy } from "@/content/copy";

export default function Home() {
  return <main><a className="story-skip" href="#close">{copy.skipLabel}</a><Experience>
    {story.chapters.map((chapter, index) => <Chapter key={chapter.id} id={chapter.id}>
      {chapter.beats.map((beat, beatIndex) => {
        const words = copy.beats[beat.id];
        return <Beat key={beat.id} story={story} id={beat.id} fallback={index === 1 ?
          // A local SVG is already sized; no image optimizer or network is needed.
          // eslint-disable-next-line @next/next/no-img-element
          <img src="/plain/fan.svg" width="640" height="300" alt={copy.pictureAlt} /> : undefined}>
          <Kicker number={chapter.number}>{chapter.name}</Kicker>
          <Title id={`${beatIndex === 0 ? chapter.id : beat.id}-title`} as={index === 0 && beatIndex === 0 ? "h1" : "h2"}>{words.title}</Title>
          <Body>{words.body}</Body>
          <Note>{words.note}</Note>
          {index === 2 && <a href="#opening">{copy.backLabel}</a>}
        </Beat>;
      })}
    </Chapter>)}
  </Experience></main>;
}
